# Extensible declarative READ_ONLY_SQL schema metadata registry, owned by the
# single canonical capability SQL_SCHEMA_METADATA_AUDIT_READONLY.
# Callers never supply arbitrary SQL, connections, or tables outside an
# allow-listed, preapproved readonly_audit_profiles profile on EDARSAHUB.
_SQL_METADATA_PROFILE_RE = _g3_re.compile(r"^[a-z0-9][a-z0-9_.-]{2,80}$")
_SQL_METADATA_OBJECT_RE = _g3_re.compile(r"^[A-Za-z_][A-Za-z0-9_]{1,127}$")


@dataclass(frozen=True)
class SqlSchemaMetadataProfile:
    bounded_context: str
    profile: str
    allowed_objects: tuple[str, ...]
    source: str = "EDARSAHUB"


_SQL_SCHEMA_METADATA_PROFILES: dict[str, SqlSchemaMetadataProfile] = {}
_SQL_SCHEMA_METADATA_DOMAINS: dict[str, tuple[str, ...]] = {}


def register_sql_schema_metadata_profile(
    spec: SqlSchemaMetadataProfile,
) -> SqlSchemaMetadataProfile:
    """Register one immutable, audited, EDARSAHUB-only READ_ONLY_SQL metadata profile."""
    from tools.mirror_sync.readonly_audit_profiles import is_allowed_readonly_audit_profile

    if not isinstance(spec, SqlSchemaMetadataProfile):
        raise SemanticCapabilityError("SQL_METADATA_PROFILE_INVALID")
    context = str(spec.bounded_context or "").strip().upper()
    if not context or not _PYTEST_SUITE_CONTEXT_RE.fullmatch(context):
        raise SemanticCapabilityError("SQL_METADATA_CONTEXT_INVALID")
    profile = str(spec.profile or "").strip()
    if not profile or not _SQL_METADATA_PROFILE_RE.fullmatch(profile):
        raise SemanticCapabilityError("SQL_METADATA_PROFILE_NAME_INVALID")
    if not is_allowed_readonly_audit_profile(profile):
        raise SemanticCapabilityError("SQL_METADATA_PROFILE_NOT_ALLOWLISTED")
    if profile in _SQL_SCHEMA_METADATA_PROFILES:
        raise SemanticCapabilityError(f"SQL_METADATA_PROFILE_DUPLICATE:{profile}")
    source = str(spec.source or "").strip().upper()
    if source != "EDARSAHUB":
        raise SemanticCapabilityError("SQL_METADATA_SOURCE_FORBIDDEN")
    if not isinstance(spec.allowed_objects, (tuple, list)) or not spec.allowed_objects:
        raise SemanticCapabilityError("SQL_METADATA_OBJECTS_EMPTY")
    normalized_objects = tuple(str(obj or "").strip() for obj in spec.allowed_objects)
    if any(not _SQL_METADATA_OBJECT_RE.fullmatch(obj) for obj in normalized_objects):
        raise SemanticCapabilityError("SQL_METADATA_OBJECT_INVALID")
    if len(set(normalized_objects)) != len(normalized_objects):
        raise SemanticCapabilityError("SQL_METADATA_OBJECT_DUPLICATE")

    normalized = SqlSchemaMetadataProfile(
        bounded_context=context,
        profile=profile,
        allowed_objects=normalized_objects,
        source="EDARSAHUB",
    )
    _SQL_SCHEMA_METADATA_PROFILES[profile] = normalized
    existing_domain_profiles = _SQL_SCHEMA_METADATA_DOMAINS.get(context, ())
    _SQL_SCHEMA_METADATA_DOMAINS[context] = tuple(
        sorted((*existing_domain_profiles, profile))
    )
    return normalized


def sql_schema_metadata_profiles() -> dict[str, SqlSchemaMetadataProfile]:
    return dict(_SQL_SCHEMA_METADATA_PROFILES)


