def _sql_schema_metadata_audit_readonly_builder(
    request: Mapping[str, Any],
) -> dict[str, Any]:
    from tools.mirror_sync.readonly_audit_profiles import build_readonly_audit_checks

    context = _g3_context(request)
    domain_profiles = _SQL_SCHEMA_METADATA_DOMAINS.get(context)
    if not domain_profiles:
        raise SemanticCapabilityError("SEMANTIC_BOUNDED_CONTEXT_UNSUPPORTED")

    c = _g3_constraints(request, {"profile"})
    raw_profile = c.get("profile")
    if raw_profile is None:
        if len(domain_profiles) != 1:
            raise SemanticCapabilityError("SEMANTIC_SQL_PROFILE_REQUIRED")
        selected_profile = domain_profiles[0]
    else:
        if not isinstance(raw_profile, str):
            raise SemanticCapabilityError("SEMANTIC_SQL_PROFILE_INVALID")
        selected_profile = raw_profile.strip()
        if selected_profile not in domain_profiles:
            raise SemanticCapabilityError("SEMANTIC_SQL_PROFILE_INVALID")

    spec = _SQL_SCHEMA_METADATA_PROFILES.get(selected_profile)
    if spec is None or spec.bounded_context != context or spec.source != "EDARSAHUB":
        raise SemanticCapabilityError("SEMANTIC_SQL_PROFILE_INVALID")

    checks = build_readonly_audit_checks(spec.profile)
    if not checks or any(
        not isinstance(chk, dict)
        or chk.get("type") != "sql_readonly_audit"
        or str(chk.get("source") or "").strip().upper() != "EDARSAHUB"
        for chk in checks
    ):
        raise SemanticCapabilityError("SEMANTIC_SQL_PROFILE_INVALID")

    return {
        "actions": [],
        "checks": checks,
        "scheduling": _g3_scheduling(context),
    }


